	private static final class MemorySampler implements AutoCloseable {
		private static final List<BufferPoolMXBean> BUFFER_POOLS = ManagementFactory
				.getPlatformMXBeans(BufferPoolMXBean.class);

		private volatile boolean running = true;
		private volatile long peakHeapBytes;
		private volatile long peakDirectBytes;
		private final Thread sampler;

		private MemorySampler() {
			sample();
			sampler = Thread.ofPlatform()
					.daemon()
					.name("lmdb-bulk-benchmark-memory-sampler")
					.start(this::sampleUntilClosed);
		}

		private void sampleUntilClosed() {
			while (running) {
				sample();
				LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(1));
			}
			sample();
		}

		private void sample() {
			peakHeapBytes = Math.max(peakHeapBytes,
					ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());
			long directBytes = 0L;
			for (BufferPoolMXBean pool : BUFFER_POOLS) {
				if ("direct".equals(pool.getName())) {
					directBytes += pool.getMemoryUsed();
				}
			}
			peakDirectBytes = Math.max(peakDirectBytes, directBytes);
		}

		private void record(LoadCounters counters) {
			sample();
			counters.peakHeapBytes = Math.max(counters.peakHeapBytes, peakHeapBytes);
			counters.peakDirectBytes = Math.max(counters.peakDirectBytes, peakDirectBytes);
		}

		@Override
		public void close() {
			running = false;
			try {
				sampler.join();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
		}
	}

